/*
 * A358424  Numbers k such that A030717(k) = 6.
 * https://oeis.org/A358424
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = n-th k such that A030717(k) = 6; found by scanning k = 1,
 *            2, 3, ... with A030717 generated by its list procedure
 * Range:     u8 n <= 12, u16 n <= 472, u32 n <= 6070, u64 n <= 6070,
 *            u128 n <= 6070, big any n
 * Validated: standard, pass, 70 terms through n = 5645 (2026-11-10)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stddef.h>
#include "../utils/mem.h"

typedef struct {
    seq_t *keys;
    seq_t *counts;
    size_t cap;
    size_t mask;
    size_t size;
} A030717_Map;

static inline uint64_t A030717_hash(seq_t x)
{
    return (uint64_t)x;
}

static void A030717_map_init(A030717_Map *m)
{
    m->cap   = 1 << 15;
    m->mask  = m->cap - 1;
    m->size  = 0;
    m->keys  = mem_new(seq_t, m->cap);
    m->counts = mem_new(seq_t, m->cap);
}

static void A030717_map_rehash(A030717_Map *m, size_t new_cap)
{
    seq_t *new_keys   = mem_new(seq_t, new_cap);
    seq_t *new_counts = mem_new(seq_t, new_cap);
    size_t new_mask   = new_cap - 1;

    for (size_t i = 0; i < m->cap; ++i) {
        if (m->keys[i] != 0) {
            uint64_t h = A030717_hash(m->keys[i]) & new_mask;
            while (new_keys[h] != 0) h = (h + 1) & new_mask;
            new_keys[h]   = m->keys[i];
            new_counts[h] = m->counts[i];
        }
    }
    mem_free(m->keys);
    mem_free(m->counts);
    m->keys   = new_keys;
    m->counts = new_counts;
    m->cap    = new_cap;
    m->mask   = new_mask;
}

static void A030717_map_ensure(A030717_Map *m)
{
    if (m->size > m->cap / 2) {
        A030717_map_rehash(m, m->cap << 1);
    }
}

static void A030717_map_increment(A030717_Map *m, seq_t key)
{
    uint64_t h = A030717_hash(key) & m->mask;
    while (m->keys[h] != 0) {
        if (m->keys[h] == key) {
            m->counts[h] += 1;
            return;
        }
        h = (h + 1) & m->mask;
    }
    m->keys[h]   = key;
    m->counts[h] = 1;
    m->size++;
    A030717_map_ensure(m);
}

typedef struct { seq_t key; seq_t count; } A030717_KV;

static int A030717_cmp_KV(const void *a, const void *b)
{
    const A030717_KV *x = (const A030717_KV*)a;
    const A030717_KV *y = (const A030717_KV*)b;
    return (x->key < y->key) ? -1 : (x->key > y->key);
}

static seq_t A030717_a(idx_t n)
{
    static bool     init_done = false;
    static seq_t   *list      = NULL;
    static size_t   list_len  = 0;
    static size_t   list_cap  = 0;
    static A030717_Map map;
    static A030717_KV *kv_buf = NULL;
    static size_t   kv_cap    = 0;

    if (!init_done) {
        list_cap  = 128;
        list      = mem_new(seq_t, list_cap);
        list[0]   = (seq_t)1;
        list_len  = 1;

        A030717_map_init(&map);
        A030717_map_increment(&map, (seq_t)1);

        kv_cap = 1024;
        kv_buf = mem_new(A030717_KV, kv_cap);

        init_done = true;
    }

    while (list_len < (size_t)n) {
        if (map.size > kv_cap) {
            kv_cap = map.size * 2;
            kv_buf = mem_resize(A030717_KV, kv_buf, kv_cap);
        }

        size_t kv_len = 0;
        for (size_t i = 0; i < map.cap; ++i) {
            if (map.keys[i] != 0) {
                kv_buf[kv_len].key   = map.keys[i];
                kv_buf[kv_len].count = map.counts[i];
                ++kv_len;
            }
        }

        mem_qsort(kv_buf, kv_len, sizeof(A030717_KV), A030717_cmp_KV);

        if (list_len + kv_len > list_cap) {
            size_t new_cap = list_cap;
            while (new_cap < list_len + kv_len) new_cap <<= 1;
            list = mem_resize(seq_t, list, new_cap);
            list_cap = new_cap;
        }

        for (size_t i = 0; i < kv_len; ++i) {
            list[list_len++] = kv_buf[i].count;
            A030717_map_increment(&map, kv_buf[i].count);
        }
    }

    return list[n - 1];
}

seq_t a(idx_t n)
{
    static idx_t *found = NULL;
    static size_t found_len = 0;
    static size_t found_cap = 0;
    static idx_t next_k = 1;

    while (found_len < (size_t)n) {
        idx_t k = next_k++;
        if (A030717_a(k) == 6) {
            if (found_len >= found_cap) {
                found_cap = found_cap ? found_cap * 2 : 256;
                found = (idx_t *)realloc(found, found_cap * sizeof(idx_t));
            }
            found[found_len++] = k;
        }
    }
    return (seq_t)found[n - 1];
}
